-- Venue Live Guest "Birthday Pink Paradise". Aditif & idempoten. Jalankan SETELAH admin-live-event-aqiqah.sql (jenis acara pinkparadise), admin-live-theme.sql, admin-live-decor.sql, admin-live-decor-avatars.sql, dan admin-live-decor-garden-layout.sql (skrip tata letak itu melewati venue ini karena ukuran/posisi dekornya diatur sendiri).
insert into public.live_venues (key, name, event_type, areas, max_guests, active, sort, bg_pos, nm_theme)
select 'pinkparadise', 'Birthday Pink Paradise (balon & bunga)', 'pinkparadise', coalesce((select areas from public.live_venues where key = 'little-ballerina'), '[]'::jsonb), 300, false, 126, 'center 38%',
  $t${"name":"Pink Paradise","orn":"blossom","ui":{"ivory":"#FFF5F2","white":"#FFFFFF","soft":"#FFE0E8","soft2":"#F5B5C8","accent":"#E0557F","deep":"#7A2342","ink":"#4A1B2E","mute":"#9A6B7C","line":"#F7D0DB","serif":"\"Fredoka\",system-ui,sans-serif","sans":"Inter,system-ui,sans-serif","rad":18,"btnr":14,"btnt":"none","btnls":".02em"},"mono":{"font":"\"Fredoka\",system-ui,sans-serif","it":0,"paper":"#FFF9F6","ink":"#4A1B2E","accent":"#E0557F","gold":"#E8A94A","leaf":"#FFE0E8","hbg":"rgba(255,245,242,.94)","hline":"#F5B5C8","motif":"blossom"},"hud":{"bg":"rgba(122,35,66,.84)","acc":"#FFD6A5","on":"#4A1B2E"},"scr":{"wine":"#7A2342","veil":"255,245,242"}}$t$::jsonb
where not exists (select 1 from public.live_venues where key = 'pinkparadise');
update public.live_venues set decor = $d${"rope":{"url":"/assets/live-decor/pinkparadise/rope.webp","w":6.5,"x":0,"z":-27.5},"speakers":{"url":"/assets/live-decor/pinkparadise/speakers.webp","w":2.2},"balloons":{"url":"/assets/live-decor/pinkparadise/balloons.webp","w":1.6},"stall_snacks":{"url":"/assets/live-decor/pinkparadise/stall_snacks.webp","w":2.0},"stall_candy":{"url":"/assets/live-decor/pinkparadise/stall_candy.webp","w":1.4},"stall_drinks":{"url":"/assets/live-decor/pinkparadise/stall_drinks.webp","w":4.8},"photobooth":{"url":"/assets/live-decor/pinkparadise/photobooth.webp","w":5.6},"claw":{"url":"/assets/live-decor/pinkparadise/claw.webp","w":4.4},"arch":{"url":"/assets/live-decor/pinkparadise/arch.webp"},"fountain":{"url":"/assets/live-decor/pinkparadise/fountain.webp","w":5.8},"sign":{"url":"/assets/live-decor/pinkparadise/sign.webp","w":1.5},"easel":{"url":"/assets/live-decor/pinkparadise/easel.webp","w":2.8,"x":4.6,"z":8.2},"table":{"url":"/assets/live-decor/pinkparadise/table.webp"},"banner":{"url":"/assets/live-decor/pinkparadise/banner.webp","w":1.8},"gifts":{"url":"/assets/live-decor/pinkparadise/gifts.webp","w":1.8},"av_host":{"url":"/assets/live-decor/pinkparadise/av_host.webp","name":"Sasha Gaun Hibiscus"},"av_l1":{"url":"/assets/live-decor/pinkparadise/av_l1.webp","name":"Kak Kalung Bunga"},"av_l2":{"url":"/assets/live-decor/pinkparadise/av_l2.webp","name":"Kak Topi Kacamata"},"av_l3":{"url":"/assets/live-decor/pinkparadise/av_l3.webp","name":"Kak Kamera"},"av_p1":{"url":"/assets/live-decor/pinkparadise/av_p1.webp","name":"Kak Gaun Hibiscus"},"av_p2":{"url":"/assets/live-decor/pinkparadise/av_p2.webp","name":"Kak Hijab Pink"},"av_p3":{"url":"/assets/live-decor/pinkparadise/av_p3.webp","name":"Kak Topi Kelapa"}}$d$::jsonb, background_url = '/assets/live-decor/pinkparadise/painting.webp', active = true, updated_at = now() where key = 'pinkparadise';
